assignments.value:
={{(() => {
  try {
    const ids = $json.mensaje_final.map(n => {
      const parsed = typeof n === 'string' ? JSON.parse(n) : n;
      return parsed.sessionid;
    });
    const uniqueIds = [...new Set(ids)];
    return uniqueIds[0] || null;
  } catch (e) {
    return `Error: ${e.message}`;
  }
})()}}

conditions.leftValue:
={{ (() => {
  try {
    const mensajes = $json.ClasificarMensaje;
    if (!mensajes || !Array.isArray(mensajes) || mensajes.length === 0) return new Date(0);

    // Buscar el último mensaje con fecha válida
    const ultimoConFecha = [...mensajes].reverse().find(m => {
      const data = typeof m === 'string' ? JSON.parse(m) : m;
      return data.fecha && data.fecha !== 'null' && data.fecha.trim() !== '';
    });

    if (!ultimoConFecha) return new Date(0);

    const data = typeof ultimoConFecha === 'string' ? JSON.parse(ultimoConFecha) : ultimoConFecha;

    const fechaValida = new Date(data.fecha);
    return isNaN(fechaValida.getTime()) ? new Date(0) : fechaValida;
  } catch (error) {
    return new Date(0);
  }
})() }}

assignments.value:
={{ (() => {
  try {
    const mensajes = $json.ClasificarMensaje;
    if (!mensajes || !Array.isArray(mensajes) || mensajes.length === 0) return null;

    const ultimo = mensajes[mensajes.length - 1];
    const data = typeof ultimo === 'string' ? JSON.parse(ultimo) : ultimo;

    return data.fecha || null;
  } catch (error) {
    return null;
  }
})() }}
